sp_widget.client_script:
(function() {
    if (data.offboardingStatusList && data.offboardingStatusList.length > 0) {
        api.controller.setData('offboardingStatusList', data.offboardingStatusList);
    } else {
        api.controller.setData('noOffboardingStatusMessage', "No offboarding requests at the moment.");
    }
})();

sp_widget.css:
/* Container for the widget */
.offboarding-status-widget {
    font-family: 'Arial', sans-serif;
    background-color: #f9f9f9;
    padding: 15px;
    border-radius: 5px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

/* Each item in the offboarding status list */
.offboarding-status-item {
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 5px;
    margin-bottom: 10px;
    padding: 10px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

/* Hover effect on each item */
.offboarding-status-item:hover {
    transform: scale(1.02);
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* Title for the request */
.offboarding-status-item strong {
    color: #333;
}

/* No data message styling */
.offboarding-status-widget p {
    color: #888;
    font-size: 14px;
}

sp_widget.script:
(function() {
    var offboardingStatusList = [];

    // Query the Offboarding Request table for the current user's active requests
    var offboardingGr = new GlideRecord('x_1583423_hr_hroo_employee_offboarding'); // Replace with your actual Offboarding Request table name
    offboardingGr.addQuery('state', '!=', 'Complete'); // Only include records that are not yet completed
    offboardingGr.addQuery('requested_for', gs.getUserID()); // Filter by the logged-in user
    offboardingGr.query();

    // Collect relevant information for each request
    while (offboardingGr.next()) {
        offboardingStatusList.push({
            request_number: offboardingGr.number,
            status: offboardingGr.state.getDisplayValue(),
            requested_for: offboardingGr.requested_for.getDisplayValue(),
            date_requested: offboardingGr.sys_created_on.getDisplayValue()
        });
    }

    // Pass the collected data to the widget's client script
    data.offboardingStatusList = offboardingStatusList;
})();
